            if until > now {
                break;
            }
            self.set_phase(arrival, Phase::Visible);
        }
    }

    pub fn update(
        &mut self,
        requested: &RequestedAttributes,
        dead_letter: Option<DeadLetter>,
        now: Time,
    ) {
