        json!({"Command": "SendMessage", "QueueName": "dead.fifo", "Body": "x", "GroupId": "g", "DeduplicationId": "d"}),
        json!({"Command": "SendMessage", "QueueName": "q.fifo", "Body": "y", "GroupId": "g", "DeduplicationId": "e"}),
        json!({"Command": "ReceiveMessage", "QueueName": "q.fifo"}),
        json!({"Command": "ReceiveMessage", "QueueName": "q.fifo"}),
