    ]);
    assert_eq!(responses[6]["Counts"], json!({"Visible": 0, "InFlight": 1, "Delayed": 0}));
    assert_eq!(responses[9]["Counts"], json!({"Visible": 0, "InFlight": 1, "Delayed": 0}));
    assert_eq!(responses[11]["Counts"], json!({"Visible": 0, "InFlight": 0, "Delayed": 0}));
